// Render test on the REAL KJV (PLAN.md 2.6 / 2.8): for John 3, Matthew 5,
// Mark 8, Revelation 1 and 22 (red boundaries) and Psalm 23 (divine name), the rendered DOM text of every verse equals the
// stored text, the `.wj` spans equal the stored red_piece ranges, `.add`/`.nd`
// equal the stored marks and `.w` spans the stored words and Strong's keys.
//
// Input: src-tauri/tests/golden/kjv-render.json, machine-generated by the Rust
// core from pipeline/out/kjv.sqlite through open_verified (a Rust test fails
// if it is stale). No Scripture is typed into this file. Regenerate (in
// src-tauri): `cargo test -- --ignored regenerate_kjv_render_golden`.
import { afterEach, beforeAll, describe, expect, it } from "vitest";
import { flushSync, mount, unmount } from "svelte";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import ChapterView from "../src/components/ChapterView.svelte";
import type { Chapter } from "../src/lib/types";
import { kjv, type KChapter } from "./kjv-golden";
import { checkColours, checkMarksAndWords, checkVerse, cp } from "./render-check";

const CSS =
  readFileSync(resolve(process.cwd(), "src/styles/tokens.css"), "utf8") +
  readFileSync(resolve(process.cwd(), "src/styles/app.css"), "utf8");

let styleEl: HTMLStyleElement;
beforeAll(() => {
  styleEl = document.createElement("style");
  styleEl.textContent = CSS;
  document.head.appendChild(styleEl);
});

let app: ReturnType<typeof mount> | null = null;
afterEach(() => {
  if (app) unmount(app);
  app = null;
  document.body.replaceChildren();
  document.documentElement.dataset.redLetters = "on";
});

function renderChapter(ch: KChapter): HTMLElement {
  const reading = document.createElement("div");
  reading.className = "reading";
  document.body.appendChild(reading);
  const book = kjv.books.find((b) => b.ord === ch.book)!;
  app = mount(ChapterView, {
    target: reading,
    props: {
      chapter: { book: ch.book, osis: ch.osis, chapter: ch.chapter, verses: ch.verses } as Chapter,
      book, highlights: {}, currentVerse: null,
      prevLabel: null, nextLabel: null, onPrev: () => {}, onNext: () => {},
    },
  });
  flushSync();
  return reading;
}

describe("render test on the real KJV", () => {
  it("golden covers the five chapters, red letters on, tricky boundaries present", () => {
    expect(kjv.translation).toEqual({ abbrev: "KJV", name: "King James Version (1769)", has_red_letters: true });
    expect(kjv.books.length).toBe(66);
    expect(kjv.chapters.map((c) => [c.osis, c.chapter])).toEqual([
      ["John", 3], ["Matt", 5], ["Mark", 8], ["Rev", 1], ["Rev", 22], ["Ps", 23],
    ]);
    const all = kjv.chapters.flatMap((c) => c.verses);
    for (const c of kjv.chapters) {
      const book = kjv.books.find((b) => b.ord === c.book)!;
      expect(c.verses.length).toBe(book.verses[c.chapter - 1]);
    }
    expect(all.some((v) => v.red.some(([s]) => s > 0))).toBe(true); // red starts mid-verse
    expect(all.some((v) => v.red.some(([, e]) => e < cp(v.text).length))).toBe(true); // red ends mid-verse
    expect(all.some((v) => v.red.length >= 2)).toBe(true); // narration inside a speech
    expect(all.some((v) => v.red.length === 0)).toBe(true);
    expect(all.some((v) => v.add.length > 0) && all.some((v) => v.nd.length > 0)).toBe(true);
  });

  it.each(kjv.chapters.map((c) => [`${c.osis} ${c.chapter}`, c] as const))(
    "%s: DOM text = stored text, .wj = stored red ranges, marks and words = stored rows",
    (_label, ch) => {
      const reading = renderChapter(ch);
      const verseEls = Array.from(reading.querySelectorAll<HTMLElement>(".verse"));
      expect(verseEls.map((e) => Number(e.dataset.v))).toEqual(ch.verses.map((v) => v.v));
      expect(verseEls.flatMap((el, i) => checkVerse(el, ch.verses[i]))).toEqual([]);
      expect(verseEls.flatMap((el, i) => checkMarksAndWords(el, ch.verses[i]))).toEqual([]);

      const domRed = Array.from(reading.querySelectorAll(".vtext .wj")).reduce((n, e) => n + cp(e.textContent ?? "").length, 0);
      const dbRed = ch.verses.reduce((n, v) => n + v.red.reduce((m, [s, e]) => m + e - s, 0), 0);
      expect(domRed).toBe(dbRed);

      const rs = getComputedStyle(document.documentElement);
      const red = rs.getPropertyValue("--color-red-letter").trim();
      const text = rs.getPropertyValue("--color-text").trim();
      expect(verseEls.flatMap((el, i) => checkColours(el, ch.verses[i], red, text))).toEqual([]);

      const before = reading.innerHTML;
      document.documentElement.dataset.redLetters = "off";
      flushSync();
      expect(reading.innerHTML).toBe(before);
    },
  );

  it("the word check bites (a key or a word boundary changed)", () => {
    const ch = kjv.chapters[0];
    const reading = renderChapter(ch);
    const i = ch.verses.findIndex((v) => v.words.length > 1);
    const el = reading.querySelectorAll<HTMLElement>(".verse")[i];
    const v = ch.verses[i];
    expect(checkMarksAndWords(el, v)).toEqual([]);
    const [s, e, k] = v.words[0];
    expect(checkMarksAndWords(el, { ...v, words: [[s, e, `${k} G1`], ...v.words.slice(1)] }).length).toBeGreaterThan(0);
    expect(checkMarksAndWords(el, { ...v, words: [[s, e + 1, k], ...v.words.slice(1)] }).length).toBeGreaterThan(0);
    expect(checkMarksAndWords(el, { ...v, add: v.add.length ? [] : [[0, 1]] }).length).toBeGreaterThan(0);
  });

  it("the book's stored main title shows above chapter 1 only, exactly as stored", () => {
    for (const ch of kjv.chapters) {
      const reading = renderChapter(ch);
      const book = kjv.books.find((b) => b.ord === ch.book)!;
      const title = reading.querySelector(".book-title");
      if (ch.chapter === 1) {
        expect(book.main_title).toBeTruthy();
        expect(title?.textContent).toBe(book.main_title);
        expect(title?.nextElementSibling?.matches("h1.chapter-head")).toBe(true);
      } else {
        expect(title).toBeNull();
      }
      expect(reading.querySelector("h1.chapter-head")?.textContent).toBe(
        book.chapters === 1 ? book.heading : `${book.heading} ${ch.chapter}`,
      );
      if (app) unmount(app);
      app = null;
      document.body.replaceChildren();
    }
    // every book carries its stored title (66 in the KJV, DESIGN.md 8)
    expect(kjv.books.every((b) => typeof b.main_title === "string" && b.main_title.length > 0)).toBe(true);
  });
});
